namespace MeadowPeaks;

internal static class ProfileValidator
{
    public static bool Valid(Progress? p, bool legacy = false) { int cap = legacy ? 480000 : MeadowCampaign.TotalLevels; return p != null && p.Version == 1 && p.Hearts is >=0 and <=999 && p.GemHeartProgress is >=0 and <=9 && p.WheelSpinsUsed>=0 && p.WheelSpinsUsed<=1+p.Garden/5 && p.HighestPlayedLevel>=0 && p.SeenMechanics!=null && p.SeenMechanics.All(k=>Enum.IsDefined(typeof(CardKind),k)) && p.GardenRefreshAt>=0 && p.GardenRefreshAt<=253402300799999L && double.IsFinite(p.FreshDealCooldown) && p.FreshDealCooldown>=0 && p.FreshDealCooldown<=30 && p.Favorites != null && p.Favorites.All(n=>n>=1 && n<=cap) && p.Picnic != null && p.Picnic.Day != null && p.Picnic.Day.Length<=10 && p.Picnic.Wins>=0 && p.Picnic.Wins<=1000000 && p.Picnic.Clears>=0 && p.Picnic.Clears<=1000000 && p.Picnic.GemCoins>=0 && p.Picnic.GemCoins<=1000000 && p.Picnic.Claimed>=0 && p.Picnic.Claimed<=7 && p.Coins >= 0 && p.Unlocked >= 1 && p.Unlocked <= cap && p.EndlessDeal >= 1 && p.EndlessWins >= 0 && p.ChapterGifts != null && p.ChapterGifts.All(n => n >= 1 && n <= cap / 20) && p.Items != null && p.Items.All(kv => !string.IsNullOrWhiteSpace(kv.Key) && kv.Value >= 0) && p.Stars != null && p.Scores != null && p.Stars.All(kv => kv.Key >= 1 && kv.Key <= cap && kv.Value >= 1 && kv.Value <= 3) && p.Scores.All(kv => kv.Key >= 1 && kv.Key <= cap && kv.Value >= 0) && p.Wilds >= 0 && p.Extras >= 0 && p.Hammers >= 0 && p.Garden >= 0 && p.GardenClaimed >= 0 && p.GardenClaimed <= p.Garden; }
}
